CREATE TABLE terminal_jobs(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id),runtime_id TEXT NOT NULL UNIQUE,revision INTEGER NOT NULL,source_digest TEXT NOT NULL,command TEXT NOT NULL,timeout_ms INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN ('running','succeeded','failed','cancelled','timed_out')),created_at INTEGER NOT NULL,deadline_at INTEGER NOT NULL,finished_at INTEGER,exit_code INTEGER,duration_ms INTEGER,receipt_origin TEXT NOT NULL DEFAULT 'browser-unverified');
CREATE INDEX terminal_project ON terminal_jobs(project_id,created_at);
CREATE TABLE terminal_events(job_id TEXT NOT NULL REFERENCES terminal_jobs(id) ON DELETE CASCADE,seq INTEGER NOT NULL,stream TEXT NOT NULL CHECK(stream IN ('stdout','stderr')),text TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(job_id,seq));
CREATE TRIGGER terminal_identity_immutable BEFORE UPDATE OF project_id,workspace_id,user_id,runtime_id,revision,source_digest,command,timeout_ms,created_at,deadline_at ON terminal_jobs BEGIN SELECT RAISE(ABORT,'terminal_identity_immutable'); END;
CREATE TRIGGER terminal_status_immutable BEFORE UPDATE ON terminal_jobs WHEN OLD.status <> 'running' BEGIN SELECT RAISE(ABORT,'terminal_status_immutable'); END;
CREATE UNIQUE INDEX terminal_one_active_user ON terminal_jobs(user_id) WHERE status='running';
